-- Migración 0027. DISPOSITIVOS registra equipos móviles (p. ej. CK65).
-- AUTORIZACION_TOKENS guarda tokens de acceso al API sin login web.
-- IDENTIFICADOR es el UUID estable del equipo. TOKEN es el valor que envía la app.
-- ID_DISPOSITIVO puede ser nulo hasta vincular el token a un dispositivo.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "DISPOSITIVOS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "IDENTIFICADOR" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "DISPOSITIVOS_IDENTIFICADOR_CHK" CHECK (
    length(btrim("IDENTIFICADOR")) > 0
  ),
  CONSTRAINT "DISPOSITIVOS_NOMBRE_CHK" CHECK (
    length(btrim("NOMBRE")) > 0
  )
);

CREATE TABLE "AUTORIZACION_TOKENS" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ID_DISPOSITIVO" integer,
  "TOKEN" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "EXPIRA_EN" timestamptz,
  "ULTIMO_USO_EN" timestamptz,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "AUTORIZACION_TOKENS_ID_DISPOSITIVO_FK"
    FOREIGN KEY ("ID_DISPOSITIVO") REFERENCES "DISPOSITIVOS" ("ID"),
  CONSTRAINT "AUTORIZACION_TOKENS_TOKEN_CHK" CHECK (
    length(btrim("TOKEN")) > 0
  ),
  CONSTRAINT "AUTORIZACION_TOKENS_NOMBRE_CHK" CHECK (
    length(btrim("NOMBRE")) > 0
  )
);

CREATE INDEX "AUTORIZACION_TOKENS_ID_DISPOSITIVO_IDX"
  ON "AUTORIZACION_TOKENS" ("ID_DISPOSITIVO");

CREATE INDEX "AUTORIZACION_TOKENS_ACTIVO_IDX"
  ON "AUTORIZACION_TOKENS" ("ACTIVO");

CREATE TRIGGER "DISPOSITIVOS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "DISPOSITIVOS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

CREATE TRIGGER "AUTORIZACION_TOKENS_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "AUTORIZACION_TOKENS"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

ALTER TABLE "DISPOSITIVOS" OWNER TO packing;
ALTER TABLE "AUTORIZACION_TOKENS" OWNER TO packing;

COMMIT;
